/**
 * Row shapes for the Form 141 Schedule B tables, and the pure mapping between
 * them and the engine's Form141Deal.
 *
 * These interfaces are hand-written rather than imported from
 * src/integrations/supabase/types.ts because that file is regenerated by the
 * Supabase CLI only (CLAUDE.md §6) and will not know these tables until
 * someone runs the generator after applying 20260907090000. Every query in
 * this module therefore casts the table name, the same way TdsFilings.tsx
 * already does for `tds_corrections`.
 *
 * The mapping is kept pure and in its own file so it can be unit-tested
 * without a database — and because it is the exact seam where a wrong
 * assumption would silently feed the engine bad input. Numbers arrive from
 * Postgres NUMERIC as strings often enough that coercing them in one place,
 * once, is worth a file of its own.
 */

import type {
  Form141Deal,
  Form141Buyer,
  Form141Seller,
  Form141Instalment,
  ResidentialStatus,
  PanStatus,
} from "@/lib/tds/form141ScheduleB";
import { todayInIndia } from "@/lib/tds/form141";
import type { EntityType } from "@/lib/tds/partyFieldRules";

// ─── Database rows ──────────────────────────────────────────────────────────

export type PropertyTxnStatus = "draft" | "ready" | "filed" | "archived";
export type PropertySource = "manual" | "agreement_upload";

export interface PropertyTransactionRow {
  id: string;
  firm_id: string;
  client_id: string;
  property_type: string;
  property_address: string;
  property_pin: string | null;
  date_of_agreement: string;
  date_of_registration: string | null;
  total_sale_consideration: number | string;
  total_stamp_duty_value: number | string | null;
  stamp_duty_value_as_on: string | null;
  payment_mode: "lumpsum" | "instalments";
  filing_buyer_pan: string | null;
  tax_year: string | null;
  status: PropertyTxnStatus;
  source: PropertySource;
  notes: string | null;
  created_at?: string;
  updated_at?: string;
}

export interface PropertyPartyRow {
  id: string;
  firm_id: string;
  transaction_id: string;
  party_role: "buyer" | "seller";
  seq: number;
  pan: string | null;
  name: string;
  contact: string | null;
  email: string | null;
  share_pct: number | string;
  residential_status: ResidentialStatus;
  /** Constitution — individual / huf / company / firm_llp / … Null means not
   *  yet established; the PAN's 4th character suggests it, nobody defaults it. */
  entity_type: EntityType | null;
  pan_status: PanStatus | null;
  section_395_certificate_no: string | null;
  section_395_rate: number | string | null;
  section_395_valid_from: string | null;
  section_395_valid_to: string | null;
  section_395_ceiling_amount: number | string | null;
}

export interface PropertyInstalmentRow {
  id: string;
  firm_id: string;
  transaction_id: string;
  seq: number;
  amount_paid_by_buyer: number | string;
  date_paid_or_credited: string;
  date_of_deduction: string;
  date_of_deposit: string | null;
  date_of_filing: string | null;
  /** Optional [{seller_key, amount}] split across sellers. Null = pro-rata. */
  allocations: { seller_key: string; amount: number | string }[] | null;
}

export interface PropertyFilingRow {
  id: string;
  transaction_id: string;
  instalment_id: string;
  tax_year: string;
  month_of_deduction: string;
  due_date: string;
  acknowledgement_number: string | null;
  cin: string | null;
  bsr_code: string | null;
  challan_no: string | null;
  date_of_deposit: string | null;
  total_tds: number | string | null;
  interest_amount: number | string | null;
  fee_amount: number | string | null;
  total_payable: number | string | null;
  status: "draft" | "paid" | "filed";
  certificate_issued_at: string | null;
}

/** A transaction with everything needed to compute it. */
export interface PropertyDealBundle {
  transaction: PropertyTransactionRow;
  parties: PropertyPartyRow[];
  instalments: PropertyInstalmentRow[];
  filings?: PropertyFilingRow[];
}

// ─── Coercion ───────────────────────────────────────────────────────────────

/**
 * Postgres NUMERIC comes back from PostgREST as a STRING, not a number, to
 * preserve precision that JS floats would lose. Feeding "25600000" straight
 * into the engine turns every multiplication into string concatenation or
 * NaN, so every numeric column crosses this boundary through here.
 */
export function num(v: number | string | null | undefined): number {
  if (v === null || v === undefined || v === "") return 0;
  const n = typeof v === "number" ? v : Number(v);
  return Number.isFinite(n) ? n : 0;
}

/** As `num`, but preserves a genuine absence — a missing s.395(1) rate must
 *  stay null so the engine flags it rather than reading it as 0%. */
export function numOrNull(v: number | string | null | undefined): number | null {
  if (v === null || v === undefined || v === "") return null;
  const n = typeof v === "number" ? v : Number(v);
  return Number.isFinite(n) ? n : null;
}

/** Postgres DATE arrives as "YYYY-MM-DD"; a timestamptz would carry a time.
 *  The engine compares dates as strings, so anything longer is trimmed. */
const dateOnly = (d: string): string => (d || "").slice(0, 10);

// ─── DB → engine ────────────────────────────────────────────────────────────

export function toBuyer(row: PropertyPartyRow): Form141Buyer {
  return { pan: row.pan, name: row.name, sharePct: num(row.share_pct), entityType: row.entity_type };
}

export function toSeller(row: PropertyPartyRow): Form141Seller {
  return {
    pan: row.pan,
    name: row.name,
    contact: row.contact,
    email: row.email,
    sharePct: num(row.share_pct),
    entityType: row.entity_type,
    residentialStatus: row.residential_status,
    panStatus: row.pan_status || "unknown",
    section395CertificateNo: row.section_395_certificate_no,
    section395Rate: numOrNull(row.section_395_rate),
    section395ValidFrom: row.section_395_valid_from,
    section395ValidTo: row.section_395_valid_to,
    section395CeilingAmount: numOrNull(row.section_395_ceiling_amount),
  };
}

export function toInstalment(row: PropertyInstalmentRow): Form141Instalment {
  return {
    seq: row.seq,
    amountPaidByBuyer: num(row.amount_paid_by_buyer),
    datePaidOrCredited: dateOnly(row.date_paid_or_credited),
    dateOfDeduction: dateOnly(row.date_of_deduction),
    dateOfDeposit: row.date_of_deposit ? dateOnly(row.date_of_deposit) : null,
    dateOfFiling: row.date_of_filing ? dateOnly(row.date_of_filing) : null,
    // snake_case in Postgres, camelCase in the engine — converted here, the
    // one seam where the two naming conventions meet.
    allocations: row.allocations?.length
      ? row.allocations.map((a) => ({ sellerKey: a.seller_key, amount: num(a.amount) }))
      : null,
  };
}

/**
 * Assemble the engine's input from stored rows.
 *
 * Parties are ordered by their stored `seq` — the form's own Sl. No. — so the
 * deductee rows a draft produces come out in the same order every time and in
 * the same order they were entered. Relying on the database's default row
 * order would let two identical drafts print their sellers differently.
 */
export function toForm141Deal(bundle: PropertyDealBundle): Form141Deal {
  const bySeq = (a: { seq: number }, b: { seq: number }) => a.seq - b.seq;
  const t = bundle.transaction;

  return {
    propertyType: t.property_type,
    propertyAddress: t.property_address,
    dateOfAgreement: dateOnly(t.date_of_agreement),
    dateOfRegistration: t.date_of_registration ? dateOnly(t.date_of_registration) : null,
    totalSaleConsideration: num(t.total_sale_consideration),
    totalStampDutyValue: num(t.total_stamp_duty_value),
    stampDutyValueAsOn: t.stamp_duty_value_as_on ? dateOnly(t.stamp_duty_value_as_on) : null,
    paymentMode: t.payment_mode,
    notes: t.notes,
    buyers: bundle.parties.filter((p) => p.party_role === "buyer").sort(bySeq).map(toBuyer),
    sellers: bundle.parties.filter((p) => p.party_role === "seller").sort(bySeq).map(toSeller),
    instalments: [...bundle.instalments].sort(bySeq).map(toInstalment),
  };
}

// ─── Filing buyer ───────────────────────────────────────────────────────────

/**
 * Which buyer's PAN this statement is filed under.
 *
 * ONE definition, because three sites used to answer this question and one of
 * them answered it differently. The editor and the list both fell back to the
 * first buyer when the column was null; the save path did not — so on a
 * single-buyer deal the screen showed a PAN selected, the column stayed null,
 * and the engine was handed "" at save time. It returned a `no_filing_buyer`
 * blocker, produced no statements, and the loop that writes challan details
 * silently skipped every one of them: the acknowledgement number and CIN the
 * government had issued were dropped without an error.
 *
 * The fallback is safe because a single-buyer deal has exactly one answer.
 * With two or more buyers there is a real choice and no default is honest, so
 * the caller must have made one — `filing_buyer_not_listed` then reports the
 * gap rather than a guess being quietly filed.
 */
export function resolveFilingBuyerPan(bundle: PropertyDealBundle): string {
  const stored = bundle.transaction.filing_buyer_pan;
  if (stored) return stored;
  const buyers = bundle.parties
    .filter((p) => p.party_role === "buyer")
    .sort((a, b) => a.seq - b.seq);
  return buyers.length === 1 ? buyers[0].pan || "" : "";
}

// ─── Save preconditions ─────────────────────────────────────────────────────

/**
 * What the DATABASE still refuses to store, even as a draft.
 *
 * Deliberately almost empty. It used to demand a complete transaction —
 * address, type, a consideration above zero, a share for every party and an
 * amount for every payment — because three CHECK constraints demanded exactly
 * that of every row whatever its status. The effect was that a user who
 * uploaded a deed the reader could only partly read had the Save button
 * greyed out with no way to make it go, and lost the lot on navigating away.
 * Migration 20260913140000 moved those demands to the point of FILING, where
 * they belong, and this list shrank to what Postgres will still reject.
 *
 * A draft is incomplete by definition. Saving one has to be possible from the
 * moment there is anything worth keeping.
 */
export function dbSaveBlockers(bundle: PropertyDealBundle): string[] {
  const out: string[] = [];

  for (const p of bundle.parties) {
    const who = p.name.trim() || `${p.party_role === "buyer" ? "Buyer" : "Seller"} ${p.seq}`;
    const share = num(p.share_pct);
    // Still impossible in the database, draft or not: a share is a percentage.
    if (share < 0) out.push(`${who}'s share cannot be negative.`);
    else if (share > 100) out.push(`${who}'s share of ${share}% is more than 100%.`);
  }

  for (const i of bundle.instalments) {
    if (num(i.amount_paid_by_buyer) < 0) {
      out.push(`Payment ${i.seq} cannot be a negative amount.`);
    }
  }

  return out;
}

/**
 * What a transaction needs before it can be marked ready to file.
 *
 * The old dbSaveBlockers list, moved here — nothing has been given up, it has
 * been put at the right gate. Everything below is something the Form 141
 * statement genuinely cannot be produced without: a zero share apportions no
 * tax to that seller, a zero payment computes no tax at all, and both look on
 * screen exactly like a correctly-computed nil.
 */
export function readyBlockers(bundle: PropertyDealBundle): string[] {
  const out: string[] = [];
  const t = bundle.transaction;

  if (!t.property_address.trim()) out.push("Enter the property address.");
  if (!t.property_type.trim()) out.push("Choose a property type.");
  if (num(t.total_sale_consideration) <= 0) {
    out.push("Enter the total sale consideration — it cannot be left at zero.");
  }

  for (const p of bundle.parties) {
    const who = p.name.trim() || `${p.party_role === "buyer" ? "Buyer" : "Seller"} ${p.seq}`;
    if (!p.name.trim()) out.push(`Enter a name for ${who}.`);
    const share = num(p.share_pct);
    if (share <= 0) out.push(`Enter a share percentage for ${who} — it must be more than 0.`);
    else if (share > 100) out.push(`${who}'s share of ${share}% is more than 100%.`);
  }

  for (const i of bundle.instalments) {
    if (num(i.amount_paid_by_buyer) <= 0) {
      out.push(`Enter the amount for payment ${i.seq} — it must be more than 0.`);
    }
  }

  return out;
}

// ─── Display ────────────────────────────────────────────────────────────────

/** Indian digit grouping — ₹1,28,00,000, not ₹12,800,000. Every amount a CA
 *  reads on this screen has to match the grouping on the form itself. */
export const formatInr = (n: number | string | null | undefined): string =>
  `₹${Math.round(num(n)).toLocaleString("en-IN")}`;

export const STATUS_BADGE: Record<PropertyTxnStatus, string> = {
  draft: "bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-300",
  ready: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300",
  filed: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300",
  archived: "bg-muted text-muted-foreground",
};

export const STATUS_LABEL: Record<PropertyTxnStatus, string> = {
  draft: "Draft",
  ready: "Ready to file",
  filed: "Filed",
  archived: "Archived",
};

/** A blank transaction for the "New" form. Dates default to today so the
 *  common case — a deal being recorded the day it completes — needs no typing,
 *  while the amounts start empty because guessing them would be worse than
 *  leaving them blank. */
export function emptyTransaction(clientId: string, firmId: string): PropertyTransactionRow {
  const today = todayInIndia();
  return {
    id: "",
    firm_id: firmId,
    client_id: clientId,
    property_type: "LAND",
    property_address: "",
    property_pin: null,
    date_of_agreement: today,
    date_of_registration: null,
    total_sale_consideration: 0,
    total_stamp_duty_value: null,
    stamp_duty_value_as_on: null,
    payment_mode: "lumpsum",
    filing_buyer_pan: null,
    tax_year: null,
    status: "draft",
    source: "manual",
    notes: null,
  };
}
